 21→function getInitials(email?: string | null): string {
 22→  if (!email) return "?";
 23→  const name = email.split("@")[0];
 24→  const parts = name.split(/[._-]/);
 25→  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
 26→  return name[0]?.toUpperCase() || "?";
 27→}
 28→
 29→function getUserName(email?: string | null): string {
 30→  if (!email) return "User";
 31→  const name = email.split("@")[0];
 32→  return name.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
 33→}
 34→
 35→const AppHeader = ({ onLogoClick }: { onLogoClick?: () => void }) => {
 36→  const { user, profile, isAdmin, signOut } = useAuth();
 37→  const { theme, setTheme } = useTheme();
 38→  const [authOpen, setAuthOpen] = useState(false);
 39→  const [authTab, setAuthTab] = useState<"signin" | "signup">("signin");
 40→  const navigate = useNavigate();
 41→
 42→  const openAuth = (tab: "signin" | "signup") => { setAuthTab(tab); setAuthOpen(true); };
 43→
 44→  const subCredits = profile?.subscription_credits ?? 0;
 45→  const topCredits = profile?.topup_credits ?? 0;
 46→  const bonusCredits = profile?.bonus_credits ?? 0;
 47→  const splitTotal = subCredits + topCredits + bonusCredits;
 48→  const legacyCredits = profile?.credits ?? 0;
 49→  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
 50→  const isLowCredits = totalCredits < 3;
 51→
 52→  const initials = getInitials(user?.email);
 53→
 54→  return (
 55→    <>
 56→      <header className="border-b border-border bg-card">
 57→        <div className="mx-auto max-w-[1200px] px-4 sm:px-6 flex items-center justify-between h-14">
 58→          <Link to="/" className="flex items-center gap-2" onClick={(e) => { if (onLogoClick) { e.preventDefault(); onLogoClick(); } }}>
 59→            <Zap className="h-5 w-5 text-primary" />
 60→            <span className="font-semibold text-foreground tracking-tight">Rankora</span>
 61→          </Link>
 62→
 63→          <div className="flex items-center gap-2">
 64→            {user ? (
 65→              <>
 66→                {/* Credits */}
 67→                <button
 68→                  onClick={() => navigate("/billing")}
 69→                  className={`group inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 outline-none focus-visible:ring-2 focus-visible:ring-offset-2 border ${
 70→                    isLowCredits
 71→                      ? "border-destructive/40 text-destructive hover:border-destructive hover:bg-destructive/5 focus-visible:ring-destructive"
 72→                      : "border-border text-foreground hover:border-foreground/40 hover:bg-muted focus-visible:ring-ring"
 73→                  }`}
 74→                >
 75→                  {isLowCredits ? <AlertTriangle className="h-4 w-4" /> : <Wallet className="h-4 w-4 text-muted-foreground" />}
 76→                  <span className="text-sm font-medium tabular-nums">{totalCredits}</span>
 77→                  <span className="text-[11px] font-medium text-muted-foreground">Credits</span>
 78→                </button>
 79→
 80→                {/* Profile dropdown */}
 81→                <DropdownMenu>
 82→                  <DropdownMenuTrigger asChild>
 83→                    <button className="h-9 w-9 rounded-lg bg-primary text-primary-foreground text-sm font-bold flex items-center justify-center hover:bg-primary/90 transition-all cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1" aria-label="Account menu">
 84→                      {initials}
 85→                    </button>
 86→                  </DropdownMenuTrigger>
 87→                  <DropdownMenuContent align="end" className="w-56 mt-1.5 p-0">
 88→                    {/* User info header */}
 89→                    <div className="px-4 py-3">
 90→                      <p className="text-sm font-semibold text-foreground">{getUserName(user.email)}</p>
 91→                      <p className="text-xs text-muted-foreground truncate">{user.email}</p>
 92→                    </div>
 93→
 94→                    <DropdownMenuSeparator className="m-0" />
 95→
 96→                    {/* Theme switcher */}
 97→                    <div className="px-4 py-2.5 flex items-center justify-between">
 98→                      <span className="text-sm text-foreground">Theme</span>
 99→                      <div className="flex items-center rounded-lg border border-border bg-muted/50 p-0.5">
100→                        <button
101→                          onClick={(e) => { e.preventDefault(); setTheme("light"); }}
102→                          className={`p-1.5 rounded-md transition-colors ${theme === "light" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`}
103→                          aria-label="Light theme"
104→                        >
105→                          <Sun className="h-3.5 w-3.5" />
106→                        </button>
107→                        <button
108→                          onClick={(e) => { e.preventDefault(); setTheme("dark"); }}
109→                          className={`p-1.5 rounded-md transition-colors ${theme === "dark" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`}
110→                          aria-label="Dark theme"
111→                        >
112→                          <Moon className="h-3.5 w-3.5" />
113→                        </button>
114→                        <button
115→                          onClick={(e) => { e.preventDefault(); setTheme("system"); }}
116→                          className={`p-1.5 rounded-md transition-colors ${theme === "system" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`}
117→                          aria-label="System theme"
118→                        >
119→                          <Monitor className="h-3.5 w-3.5" />
120→                        </button>
121→                      </div>
122→                    </div>
123→
124→                    <DropdownMenuSeparator className="m-0" />
125→
126→                    {/* Menu items */}
127→                    <div className="py-1">
128→                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/profile")}>
129→                        <User className="h-4 w-4 mr-2.5" />
130→                        Profile
131→                      </DropdownMenuItem>
132→                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/billing")}>
133→                        <CreditCard className="h-4 w-4 mr-2.5" />
134→                        Billing & Plan
135→                      </DropdownMenuItem>
136→                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/settings")}>
137→                        <Settings className="h-4 w-4 mr-2.5" />
138→                        Settings
139→                      </DropdownMenuItem>
140→                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/book-demo")}>
141→                        <CalendarCheck className="h-4 w-4 mr-2.5" />
142→                        Book Demo
143→                      </DropdownMenuItem>
144→                      {isAdmin && (
145→                        <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/admin")}>
146→                          <ShieldCheck className="h-4 w-4 mr-2.5" />
147→                          Admin
148→                        </DropdownMenuItem>
149→                      )}
150→                    </div>
151→
152→                    <DropdownMenuSeparator className="m-0" />
153→
154→                    <div className="py-1">
155→                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={signOut}>
156→                        <LogOut className="h-4 w-4 mr-2.5" />
157→                        Log out
158→                      </DropdownMenuItem>
159→                    </div>
160→                  </DropdownMenuContent>
161→                </DropdownMenu>
162→              </>
163→            ) : (
164→              <>
165→                <Button variant="ghost" size="sm" onClick={() => openAuth("signin")}>Sign in</Button>
166→                <Button size="sm" onClick={() => openAuth("signup")}>Sign up free</Button>
167→              </>
168→            )}
169→          </div>
170→        </div>
171→      </header>
172→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
173→    </>
174→  );
175→};
176→
177→export default AppHeader;
