 39→
 40→interface PastJob {
 41→  id: string;
 42→  title: string | null;
 43→  job_description: string;
 44→  status: string;
 45→  created_at: string;
 46→  resume_count: number;
 47→}
 48→
 49→interface JobSidebarProps {
 50→  pastJobs: PastJob[];
 51→  selectedJobId: string | null;
 52→  showDashboard?: boolean;
 53→  loadingPastJobs: boolean;
 54→  onSelectJob: (jobId: string) => void;
 55→  onNewJob: () => void;
 56→  onDashboard?: () => void;
 57→  onRenameJob: (jobId: string, newTitle: string) => void;
 58→  onDeleteJob: (jobId: string) => void;
 59→  onAuthRequired?: () => void;
 60→  isAuthenticated?: boolean;
 61→}
 62→
 63→function getDisplayTitle(job: PastJob): string {
 64→  if (job.title) return job.title;
 65→  const firstLine = job.job_description.trim().split("\n")[0].trim();
 66→  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
 67→}
 68→
 69→const JobSidebar = ({ pastJobs, selectedJobId, showDashboard, loadingPastJobs, onSelectJob, onNewJob, onDashboard, onRenameJob, onDeleteJob, onAuthRequired, isAuthenticated = true }: JobSidebarProps) => {
 70→  const [search, setSearch] = useState("");
 71→  const [editingId, setEditingId] = useState<string | null>(null);
 72→  const [editValue, setEditValue] = useState("");
 73→  const [deleteJobId, setDeleteJobId] = useState<string | null>(null);
 74→  const editInputRef = useRef<HTMLInputElement>(null);
 75→
 76→  const filteredJobs = useMemo(() => {
 77→    if (!search.trim()) return pastJobs;
 78→    const q = search.toLowerCase();
 79→    return pastJobs.filter(
 80→      (job) =>
 81→        getDisplayTitle(job).toLowerCase().includes(q) ||
 82→        job.job_description.toLowerCase().includes(q)
 83→    );
 84→  }, [pastJobs, search]);
 85→
 86→  useEffect(() => {
 87→    if (editingId && editInputRef.current) {
 88→      editInputRef.current.focus();
 89→      editInputRef.current.select();
 90→    }
 91→  }, [editingId]);
 92→
 93→  const startEditing = (job: PastJob) => {
 94→    setEditingId(job.id);
 95→    setEditValue(getDisplayTitle(job));
 96→  };
 97→
 98→  const saveRename = async () => {
 99→    if (!editingId || !editValue.trim()) {
100→      setEditingId(null);
101→      return;
102→    }
103→    try {
104→      const { error } = await supabase
105→        .from("jobs")
106→        .update({ title: editValue.trim() } as any)
107→        .eq("id", editingId);
108→      if (error) throw error;
109→      onRenameJob(editingId, editValue.trim());
110→      toast.success("Job renamed");
111→    } catch {
112→      toast.error("Failed to rename job");
113→    }
114→    setEditingId(null);
115→  };
116→
117→  const cancelEditing = () => setEditingId(null);
118→
119→  const confirmDelete = () => {
120→    if (deleteJobId) {
121→      onDeleteJob(deleteJobId);
122→      setDeleteJobId(null);
123→    }
124→  };
125→
126→  return (
127→    <>
128→      <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
129→        <SidebarContent>
130→          {/* HOME section */}
131→          <SidebarGroup>
132→            <SidebarGroupLabel>Home</SidebarGroupLabel>
133→            <SidebarGroupContent>
134→              <SidebarMenu>
135→                {isAuthenticated && onDashboard && (
136→                  <SidebarMenuItem>
137→                    <SidebarMenuButton isActive={showDashboard && !selectedJobId} onClick={onDashboard}>
138→                      <Home className="h-4 w-4" />
139→                      <span>Dashboard</span>
140→                    </SidebarMenuButton>
141→                  </SidebarMenuItem>
142→                )}
143→              </SidebarMenu>
144→            </SidebarGroupContent>
145→          </SidebarGroup>
146→
147→          <SidebarSeparator />
148→
149→          {/* JOBS section */}
150→          <SidebarGroup className="flex-1">
151→            <SidebarGroupLabel className="flex items-center gap-2">
152→              <span>Jobs</span>
153→              {search && <span className="ml-auto text-[11px]">({filteredJobs.length})</span>}
154→            </SidebarGroupLabel>
155→            <SidebarGroupContent className="space-y-2">
156→              {/* New Job + Search */}
157→              <div className="px-2 space-y-2">
158→                <Button
159→                  size="sm"
160→                  className="w-full gap-1.5"
161→                  onClick={() => { if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; } onNewJob(); }}
162→                >
163→                  <Plus className="h-3.5 w-3.5" /> New Job
164→                </Button>
165→                <div className="relative">
166→                  <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
167→                  <SidebarInput
168→                    placeholder="Search jobs…"
169→                    value={search}
170→                    onChange={(e) => setSearch(e.target.value)}
171→                    className="pl-8 pr-7"
172→                  />
173→                  {search && (
174→                    <button
175→                      onClick={() => setSearch("")}
176→                      className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
177→                      aria-label="Clear search"
178→                    >
179→                      <X className="h-3.5 w-3.5" />
180→                    </button>
181→                  )}
182→                </div>
183→              </div>
184→
185→              {!isAuthenticated ? (
186→                <div className="px-3 py-3">
187→                  <button
188→                    onClick={() => onAuthRequired?.()}
189→                    className="w-full rounded-lg border border-dashed border-border px-3 py-5 text-center hover:border-primary/50 hover:bg-primary/5 transition-all group"
190→                  >
191→                    <Briefcase className="h-5 w-5 text-muted-foreground group-hover:text-primary mx-auto mb-2 transition-colors" />
192→                    <p className="text-xs font-medium text-foreground mb-1">No jobs yet</p>
193→                    <p className="text-[11px] text-muted-foreground mb-3">Sign in to view your job history and ranked results</p>
194→                    <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary">
195→                      Sign in to get started →
196→                    </span>
197→                  </button>
198→                </div>
199→              ) : loadingPastJobs ? (
200→                <div className="space-y-1.5 px-2">
201→                  {[0, 1, 2].map((i) => (
202→                    <div key={i} className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2" style={{ animationDelay: `${i * 80}ms`, animationFillMode: "backwards" }}>
203→                      <Skeleton className="h-4 w-3/4 bg-sidebar-accent" />
204→                      <div className="flex items-center justify-between">
205→                        <Skeleton className="h-3 w-20 bg-sidebar-accent" />
206→                        <Skeleton className="h-3 w-24 bg-sidebar-accent" />
207→                      </div>
208→                    </div>
209→                  ))}
210→                </div>
211→              ) : filteredJobs.length === 0 ? (
