213→    } catch {
214→      toast.error("Failed to delete job");
215→    }
216→  };
217→
218→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
219→    setPastJobs((prev) =>
220→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
221→    );
222→  };
223→
224→  const requireAuth = useCallback(() => {
225→    if (!user) { setAuthOpen(true); return true; }
226→    return false;
227→  }, [user]);
228→
229→  return (
230→    <SidebarProvider className="h-svh overflow-hidden">
231→      <JobSidebar
232→        pastJobs={pastJobs}
