  9→import { Loader2, Sparkles, CheckCircle2, XCircle } from "lucide-react";
 10→import { cn } from "@/lib/utils";
 11→
 12→interface QualityScore {
 13→  overall: number;
 14→  clarity: number;
 15→  keywords: number;
 16→  ats_fit: number;
 17→  inclusivity: number;
 18→}
 19→
 20→interface MissingKeyword {
 21→  keyword: string;
 22→  status: "missing" | "detected";
 23→}
 24→
 25→interface RewriteResult {
 26→  rewritten_jd: string;
 27→  quality_score: QualityScore;
 28→  missing_keywords: MissingKeyword[];
 29→}
 30→
 31→interface JDRewriteDialogProps {
 32→  open: boolean;
 33→  onOpenChange: (open: boolean) => void;
 34→  jobId: string;
 35→  originalJd: string;
 36→  onApply: (newJd: string) => void;
 37→}
 38→
 39→const SCORE_LABELS: { key: keyof Omit<QualityScore, "overall">; label: string }[] = [
 40→  { key: "clarity", label: "Clarity" },
 41→  { key: "keywords", label: "Keywords" },
 42→  { key: "ats_fit", label: "ATS Fit" },
 43→  { key: "inclusivity", label: "Inclusivity" },
 44→];
 45→
 46→function scoreColor(score: number): string {
 47→  if (score >= 75) return "bg-green-500";
 48→  if (score >= 50) return "bg-yellow-500";
 49→  return "bg-red-500";
 50→}
 51→
 52→function scoreTextColor(score: number): string {
 53→  if (score >= 75) return "text-green-600";
 54→  if (score >= 50) return "text-yellow-600";
 55→  return "text-red-600";
 56→}
 57→
 58→const JDRewriteDialog = ({ open, onOpenChange, jobId, originalJd, onApply }: JDRewriteDialogProps) => {
 59→  const [loading, setLoading] = useState(false);
 60→  const [result, setResult] = useState<RewriteResult | null>(null);
 61→  const [editedJd, setEditedJd] = useState("");
 62→
 63→  const handleRewrite = async () => {
 64→    setLoading(true);
 65→    setResult(null);
 66→    try {
 67→      const { data, error } = await supabase.functions.invoke("rewrite-jd", {
 68→        body: { job_id: jobId },
 69→      });
 70→      if (error) throw error;
 71→      if (data?.error) throw new Error(data.error);
 72→      setResult(data as RewriteResult);
 73→      setEditedJd(data.rewritten_jd);
 74→      toast.success("JD rewrite complete");
 75→    } catch (err: any) {
 76→      toast.error(err?.message || "Failed to rewrite JD");
 77→    } finally {
 78→      setLoading(false);
 79→    }
 80→  };
 81→
 82→  const handleApply = () => {
 83→    if (!editedJd.trim()) return;
 84→    onApply(editedJd);
 85→    onOpenChange(false);
 86→    toast.success("Rewritten JD applied");
 87→  };
 88→
 89→  const handleClose = () => {
 90→    if (loading) return;
 91→    onOpenChange(false);
 92→  };
 93→
 94→  const handleOpenChange = (nextOpen: boolean) => {
 95→    if (!nextOpen && loading) return;
 96→    if (!nextOpen) {
 97→      // Reset state when closing
 98→      setResult(null);
 99→      setEditedJd("");
100→    }
101→    onOpenChange(nextOpen);
102→  };
103→
104→  return (
