138→            </div>
139→          )}
140→
141→          {result && (
142→            <div className="space-y-6 pb-4">
143→              {/* Two-column JD side by side */}
144→              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
145→                <div className="flex flex-col gap-2">
146→                  <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Original JD</p>
147→                  <Textarea
148→                    readOnly
149→                    value={originalJd}
150→                    className="min-h-[280px] resize-none text-sm bg-muted/40 cursor-default"
151→                  />
152→                </div>
153→                <div className="flex flex-col gap-2">
154→                  <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
155→                    Rewritten JD
156→                    <span className="ml-2 text-[11px] normal-case font-normal text-muted-foreground">(editable)</span>
157→                  </p>
158→                  <Textarea
159→                    value={editedJd}
160→                    onChange={(e) => setEditedJd(e.target.value)}
161→                    className="min-h-[280px] resize-none text-sm"
162→                  />
163→                </div>
164→              </div>
165→
166→              {/* Quality Score */}
167→              <div className="space-y-3">
168→                <div className="flex items-center justify-between">
169→                  <p className="text-sm font-semibold">Quality Score (Original)</p>
170→                  <span className={cn("text-sm font-bold", scoreTextColor(result.quality_score.overall))}>
171→                    {result.quality_score.overall}/100
172→                  </span>
173→                </div>
174→                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
175→                  {SCORE_LABELS.map(({ key, label }) => {
176→                    const score = result.quality_score[key];
177→                    return (
178→                      <div key={key} className="space-y-1">
179→                        <div className="flex items-center justify-between text-xs">
180→                          <span className="text-muted-foreground">{label}</span>
181→                          <span className={cn("font-medium", scoreTextColor(score))}>{score}</span>
182→                        </div>
183→                        <div className="h-2 rounded-full bg-muted overflow-hidden">
184→                          <div
185→                            className={cn("h-full rounded-full transition-all duration-500", scoreColor(score))}
186→                            style={{ width: `${score}%` }}
187→                          />
188→                        </div>
189→                      </div>
190→                    );
191→                  })}
192→                </div>
193→              </div>
194→
195→              {/* Missing Keywords */}
196→              {result.missing_keywords.length > 0 && (
197→                <div className="space-y-2">
198→                  <p className="text-sm font-semibold">Keyword Analysis</p>
199→                  <div className="flex flex-wrap gap-2">
