208→                            : "border-red-500/50 text-red-700 bg-red-50 dark:text-red-400 dark:bg-red-950/30"
209→                        )}
210→                      >
211→                        {kw.status === "detected" ? (
212→                          <CheckCircle2 className="h-3 w-3" />
213→                        ) : (
214→                          <XCircle className="h-3 w-3" />
215→                        )}
216→                        {kw.keyword}
217→                      </Badge>
218→                    ))}
219→                  </div>
220→                  <p className="text-[11px] text-muted-foreground">
221→                    <span className="inline-flex items-center gap-1 text-green-600"><CheckCircle2 className="h-3 w-3" /> Detected</span>
222→                    {" "}in original JD.{" "}
223→                    <span className="inline-flex items-center gap-1 text-red-600"><XCircle className="h-3 w-3" /> Missing</span>
224→                    {" "}from original JD.
225→                  </p>
226→                </div>
227→              )}
228→            </div>
229→          )}
230→        </div>
231→
232→        <DialogFooter className="shrink-0 border-t pt-4 mt-2 gap-2">
233→          {result && (
